const measurementName = "TMS_Mag";
const tag1Name = "MAQ20";
const tag2Name = "Pressure";

const fieldNames = [
    "P1", "P2", "P3", "P4", "P5", "P6",
];


let modbusData = msg.payload;

let multiplier = 5.25 * 10 ** -6; // Apply the multiplier
modbusData = modbusData.map(value => value * multiplier);

// Step 2: Extract specific values and calculate psi0 and psi1
let Pmax = 300 // psi
let Pmin = 0 //psi

let mA = modbusData // Assuming modbusData is now the modified array
// Convert mA → psi (array)
let Amin = 0.004
let Amax = 0.020;
let psi = mA.map(i => (i - Amin) * ((Pmax - Pmin) / (Amax-Amin)) + Pmin);
// Convert psi → bar (array)
let bar = psi.map(p => 0.06894574 * p);


// Optional scaling (example)
