// ---- Build fields object ----
let fields = {};

for (let i = 0; i < Math.min(bar.length, fieldNames.length); i++) {

    let raw = Number(data[i]);
    if (!Number.isFinite(raw)) continue;

    fields[fieldNames[i]] = raw * scale[i];
}


// ---- Build final payload ----
msg.payload = [{
    measurement: measurementName,
    tags: {
        Device: tag1Name,
        Quantity: tag2Name
        },
    fields: fields
    // fields: mA
}];

return msg;

