const measurementName = "TMS_Mag";
const tag1Name = "MAQ20";
const tag2Name = "flowrate";

const fieldNames = [
    "Water_flow"
];

// Channels to include (Modbus index positions)
const enabledChannels = [6];   // example


// ---- Get Modbus Data ----
let modbusData = msg.payload;

// Apply multiplier
const multiplier = 5.25e-6;
modbusData = modbusData.map(v => v * multiplier);


// ---- Convert mA → psi ----
// flowmeter P/N: ifm SM6604
// const gpm_max = 6.6; // gpm
// const gpm_min = 0.03; // gpm

// flowmeter P/N: ifm SM8604
const gpm_max = 26.4; // gpm
const gpm_min = 0.01; // gpm

let mA = modbusData;

let gpm = mA.map(i =>
    (i - 0.004) * ((gpm_max - gpm_min) / 0.016) + gpm_min
);



// ---- Build fields object ----
let fields = {};

enabledChannels.forEach((ch, index) => {

    if (ch >= gpm.length) return;

    let raw = Number(gpm[ch]);
    if (!Number.isFinite(raw)) return;

    let fieldName = fieldNames[index] || ("ch_" + index);
    fields[fieldName] = raw;

});


// ---- Build final payload ----
msg.payload = [{
    measurement: measurementName,
    tags: {
        Device: tag1Name,
        Quantity: tag2Name
    },
    fields: fields
}];

return msg;

